using System;using System.IO;using System.Linq;using System.Collections.Generic;using V15Voice;
public static class TwoVoiceRealTests {
 static int count;static void Check(bool b,string n){if(!b)throw new Exception(n);count++;Console.WriteLine("PASS "+n);}
 public static void Main(string[] args){string root=args[0],folder=Path.Combine(Path.GetTempPath(),"V15 dual neural "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string script="1\n00:00:00,200 --> 00:00:05,000\n[A] This small detail changes the whole story.\n\n2\n00:00:05,300 --> 00:00:10,000\n[B] This small detail changes the whole story.\n\n3\n00:00:10,000 --> 00:00:15,000\n[A] Now watch what happens next.\n";string source=Path.Combine(folder,"two voices.srt");File.WriteAllText(source,script);string hash=StateFiles.Hash(source);var cues=Scripts.ParseSrt(script);bool rvc=args.Contains("--rvc");
  var a=new KokoroEngine{Root=root,Speaker=16,VoiceName="Michael",DeviceMode="cpu",Threads=2};var b=new KokoroEngine{Root=root,Speaker=3,VoiceName=rvc?"Adam RVC":"Heart",Kind=rvc?EngineKind.Rvc:EngineKind.Kokoro,ModelFolder=rvc?CommunityVoices.AdamFolder:"",DeviceMode="cpu",Threads=2};using(var e=new TwoVoiceEngine(a,b,"K:16",rvc?"C:adam_rvc":"K:3",cues)){e.Archive=new SpeechArchive(Path.Combine(folder,"state"));var o=new RenderOptions{TwoVoices=true,VoiceAInfo="Michael",VoiceBInfo=b.VoiceName,Locked=true,SlowShort=false,Breathing=BreathMode.None,ReportContext=new VoiceReportContext{SourcePath=source,SourceCues=VoiceRenderReport.Snapshot(cues)}};string wav=Renderer.Render(cues,e,o,OutputFiles.Beside(source),(percent,m)=>Console.WriteLine(percent+" "+m));Check(FinalAudio.PcmFrames(wav)==360000&&StateFiles.Hash(source)==hash,"Real two-speaker neural render produces one 15s WAV beside unchanged SRT");Check(o.RunReport.Units.Count==3&&o.RunReport.Units[0].Voice=="Michael"&&o.RunReport.Units[1].Voice==b.VoiceName&&o.RunReport.Units[2].Voice=="Michael","Actual voice map is Michael → second voice → Michael");Check(o.RunReport.Units.All(u=>u.Before>1&&u.After>1&&u.Speed<=1.3),"Each neural cue has its own measured duration and bounded speed");var data=Wave.Read(wav);Check(data.Samples.Skip(4800).Take(48000).Any(x=>Math.Abs((int)x)>100)&&data.Samples.Skip(127200).Take(48000).Any(x=>Math.Abs((int)x)>100),"Both assigned speech windows contain audible waveform");string report=File.ReadAllText(o.RunReport.PathName);Check(report.Contains("Giọng thực tế: B")&&report.Contains(b.VoiceName)&&!report.Contains("Lời: [A]")&&!report.Contains("Lời: [B]"),"Real render report keeps speaker identities separate from spoken text");
   var p=LongText.Parse("[A] This is the beginning.\n[B] Look closely at the details.\n[A] The story ends here.");var po=new RenderOptions{TwoVoices=true,Prose=true,Locked=false,Breathing=BreathMode.None,ReportContext=new VoiceReportContext{SourcePath=Path.Combine(folder,"two voices.txt")}};string text=Renderer.Render(p,e,po,Path.Combine(folder,"text.wav"),(n,m)=>{});Check(File.Exists(text)&&po.RunReport.Units.Select(u=>u.Speaker).SequenceEqual(new[]{"A","B","A"})&&Math.Abs(p.Last().End-Wave.Read(text).Duration)<1.0/24000,"Real natural TXT follows actual durations and speaker mapping");
  }Console.WriteLine("TOTAL REAL TWO VOICE "+count+" passed ("+(rvc?"Kokoro/RVC":"two Kokoro voices")+", CPU Linux). Artifacts: "+folder);
 }
}
